// Generates the self-contained local build used when index.html is opened
// directly from disk (file://), where ES module imports are blocked.
//
// Run from the repository root:
//   node web/tools/build-standalone.mjs
//
// The generated files are committed so the web app still has no runtime build
// step. Re-run this script after changing anything under web/js or web/assets.

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const webDir = path.resolve(here, '..');
const entry = path.join(webDir, 'js', 'ui', 'app.js');
const tempBundle = path.join(os.tmpdir(), `ck3dna-standalone-${process.pid}.js`);
const outputBundle = path.join(webDir, 'standalone.bundle.js');

function readJson(name) {
  return fs.readFileSync(path.join(webDir, 'assets', name), 'utf8');
}

function buildBundle() {
  const npx = process.platform === 'win32' ? 'npx.cmd' : 'npx';
  execFileSync(
    npx,
    [
      '--yes',
      'esbuild@0.25.0',
      entry,
      '--bundle',
      '--format=iife',
      '--target=es2020',
      '--charset=utf8',
      `--outfile=${tempBundle}`,
    ],
    { cwd: webDir, stdio: 'inherit', shell: process.platform === 'win32' },
  );
  return fs.readFileSync(tempBundle, 'utf8');
}

const bundle = buildBundle();
const wasmBase64 = fs
  .readFileSync(path.join(webDir, 'vendor', 'sql.js', 'sql-wasm.wasm'))
  .toString('base64');

const banner = [
  '/* Generated by web/tools/build-standalone.mjs. Do not edit by hand. */',
  `globalThis.__CK3DNA_ASSETS__ = {`,
  `  genes: ${readJson('genes.json')},`,
  `  legacy: ${readJson('legacy_genes.json')},`,
  `  translations: ${readJson('translations.json')},`,
  `};`,
  `globalThis.__CK3DNA_SQL_WASM_BASE64__ = ${JSON.stringify(wasmBase64)};`,
  '',
].join('\n');

fs.writeFileSync(outputBundle, `${banner}${bundle}`, 'utf8');
fs.rmSync(tempBundle, { force: true });

console.log(`Wrote ${path.relative(webDir, outputBundle)} (${fs.statSync(outputBundle).size} bytes)`);
